const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules/1234/timeline_events',
  qs: {
    'filters[timeline_event_id]': 'SOME_STRING_VALUE',
    'filters[timeline_event_name]': 'SOME_STRING_VALUE',
    'filters[source_activity_deleted]': 'SOME_BOOLEAN_VALUE',
    sort: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules/1234/timeline_events?filters%5Btimeline_event_id%5D=SOME_STRING_VALUE&filters%5Btimeline_event_name%5D=SOME_STRING_VALUE&filters%5Bsource_activity_deleted%5D=SOME_BOOLEAN_VALUE&sort=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

